Run it:
```js
import assert from "node:assert/strict";
const image = /^[\w-]+\.(?:jpe?g|png)$/;
for (const ok of ["cat.jpg", "my-photo.jpeg", "logo_2.png"]) assert.ok(image.test(ok), ok);
for (const bad of ["notes.txt", "image.png.exe", ".png"]) assert.ok(!image.test(bad), bad);
assert.ok(/^[\w-]+\.jpe?g|png$/.test("x.txtpng")); // ungrouped: 'png$' alone is enough
console.log("image pattern ok");
```
